export class Person {
  name: string = "";
  age: int = 0;
  active: boolean = true;
  score: number = 0.0;
}
export function test(): string {
  let p: Person = { name: "Carol", age: 42, active: false, score: 99.5 };
  let json: string = Person$toJson(p);
  let p2: Person | null = Person$fromJson(json);
  if (p2 !== null) {
    if (p2.name !== "Carol") { return "name"; }
    if (p2.age !== 42) { return "age"; }
    if (p2.active !== false) { return "active"; }
    if (p2.score !== 99.5) { return "score"; }
    return "ok";
  }
  return "null";
}

