export class User {
  name: string = "";
  nick?: string | null;
}
export function test(): string {
  let missing: User = { name: "A" };
  let missingJson: string = User$toJson(missing);
  if (missingJson !== "{\"name\":\"A\"}") { return "missing-json"; }
  let missing2: User | null = User$fromJson(missingJson);
  if (missing2 !== null) {
    if (has(missing2.nick)) { return "has-missing"; }
  } else {
    return "missing2-null";
  }
  let explicitNull: User = { name: "B", nick: null };
  let nullJson: string = User$toJson(explicitNull);
  if (nullJson !== "{\"name\":\"B\",\"nick\":null}") { return "null-json"; }
  let null2: User | null = User$fromJson(nullJson);
  if (null2 !== null) {
    if (!has(null2.nick) || null2.nick !== null) { return "null-state"; }
  } else {
    return "null2-null";
  }
  let value: User = { name: "C", nick: "cee" };
  let valueJson: string = User$toJson(value);
  if (valueJson !== "{\"name\":\"C\",\"nick\":\"cee\"}") { return "value-json"; }
  let value2: User | null = User$fromJson(valueJson);
  if (value2 !== null) {
    if (!has(value2.nick)) { return "no-value"; }
    let nick: string | null = value2.nick;
    if (nick !== null) {
      if (nick !== "cee") { return "bad-value"; }
    } else {
      return "nick-null";
    }
  } else {
    return "value2-null";
  }
  return "ok";
}

// @jsonable
export class Config {
  name: string = "";
  debug?: boolean = false;
}
export function test(): string {
  let c: Config = { name: "t" };
  if (!has(c.debug)) { return "no-default-presence"; }
  let cj: string = Config$toJson(c);
  if (cj !== "{\"name\":\"t\",\"debug\":false}") { return "cj"; }
  let c2: Config | null = Config$fromJson(cj);
  if (c2 !== null) {
    if (!has(c2.debug)) { return "no-debug"; }
    let d: boolean | null = c2.debug;
    if (d !== null) {
      if (d !== false) { return "debug-true"; }
    } else {
      return "d-null";
    }
  } else {
    return "c2-null";
  }
  let c3: Config | null = Config$fromJson("{\"name\":\"with\",\"debug\":true}");
  if (c3 !== null) {
    let d3: boolean | null = c3.debug;
    if (d3 !== null) {
      if (d3 !== true) { return "not-true"; }
    } else {
      return "d3-null";
    }
  } else {
    return "c3-null";
  }
  let c4: Config = { name: "w" };
  c4.debug = false;
  let c5: Config | null = Config$fromJson(Config$toJson(c4));
  if (c5 !== null) {
    if (!has(c5.debug)) { return "no-has-c5"; }
  } else {
    return "c5-null";
  }
  return "ok";
}

