  let n: MaybeChild | null = MaybeChild$fromJson("{\"child\":null}");
  if (n !== null) {
    if (!has(n.child)) { return "no-has-null"; }
    if (n.child !== null) { return "not-null"; }
  } else {
    return "n-null";
  }
  let v: MaybeChild | null = MaybeChild$fromJson("{\"child\":{\"value\":8}}");
  if (v !== null) {
    if (!has(v.child)) { return "no-child"; }
    let child: Child | null = v.child;
    if (child !== null) {
      if (child.value !== 8) { return "bad"; }
    } else {
      return "child-null";
    }
    let v2: MaybeChild | null = MaybeChild$fromJson(MaybeChild$toJson(v));
    if (v2 !== null) {
      let c2: Child | null = v2.child;
      if (c2 !== null) {
        if (c2.value !== 8) { return "bad2"; }
      } else {
        return "c2-null";
      }
    } else {
      return "v2-null";
    }
  } else {
    return "v-null";
  }
  let m: MaybeChild | null = MaybeChild$fromJson("{}");
  if (m !== null) {
    if (has(m.child)) { return "has-missing"; }
  } else {
    return "m-null";
  }
  return "ok";
